INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein VLAN physisch von anderen Netzwerken getrennt?', 2, '[{"text": "Nein", "correct": true, "because": "Logische Trennung auf einem Switch"}, {"text": "Ja", "correct": false, "because": "Nicht physisch isoliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für flexible Netzwerksteuerung?', 3, '[{"text": "SDN", "correct": true, "because": "Softwarebasierte Kontrolle"}, {"text": "VLAN", "correct": false, "because": "Statischer"}, {"text": "Physische Switches", "correct": false, "because": "Weniger flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen SDN für große Netze nützlich?', 5, '[{"text": "Zentrale Steuerung", "correct": true, "because": "Einheitliche Verwaltung"}, {"text": "Dynamische Anpassung", "correct": true, "because": "Flexibler Traffic"}, {"text": "Geringe Kosten", "correct": false, "because": "Setup kann teuer sein"}, {"text": "Einfache Hardware", "correct": false, "because": "Software im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) VLANs verkleinern Broadcast-Domänen. b) SDN braucht keine Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Hardware als Data Plane nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung eines VLANs?', 4, '[{"text": "Portzuordnung", "correct": false, "because": "Kern der Konfiguration"}, {"text": "Switch-Kompatibilität", "correct": false, "because": "Muss VLAN-fähig sein"}, {"text": "Grafisches Design", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SDN die Control Plane von der Data Plane trennt?', 2, '[{"text": "Ja", "correct": true, "because": "Kernprinzip von SDN"}, {"text": "Nein", "correct": false, "because": "Trennung ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für ein VLAN in einem Büro?', 3, '[{"text": "Segmentierung", "correct": true, "because": "Trennt Abteilungen"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Hardwareabhängig"}, {"text": "Einfache GUI", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein VLAN?', 5, '[{"text": "Sicherheit", "correct": true, "because": "Isoliert Traffic"}, {"text": "Flexibilität", "correct": true, "because": "Softwarebasiert anpassbar"}, {"text": "Geringere Latenz", "correct": false, "because": "Nicht primär"}, {"text": "Kostensenkung", "correct": false, "because": "Setup kann teuer sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) SDN ist nur für Rechenzentren. b) VLANs brauchen keine Router. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) auch WAN, b) Router für VLAN-Kommunikation"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für SDN in einem kleinen Netz?', 4, '[{"text": "Controller", "correct": false, "because": "Zentrale Steuerung nötig"}, {"text": "Switches", "correct": false, "because": "Data Plane erforderlich"}, {"text": "Massive Skalierung", "correct": true, "because": "Übertrieben für klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind VLANs auf Schicht 2 beschränkt?', 2, '[{"text": "Ja", "correct": true, "because": "Logische Trennung auf Link-Layer"}, {"text": "Nein", "correct": false, "because": "Schicht 2 ist Kern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für SDN in einem Campus-Netz wichtig?', 4, '[{"text": "Programmierbarkeit", "correct": true, "because": "Dynamische Anpassung"}, {"text": "Zentrales Management", "correct": true, "because": "Einheitliche Kontrolle"}, {"text": "Lokale Verarbeitung", "correct": false, "because": "Serverzentriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass VLANs die Bandbreite erhöhen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Trennung, keine Erhöhung"}, {"text": "Ja", "correct": false, "because": "Bandbreite bleibt gleich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für ein SDN-Setup?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Dynamische Steuerung zentral"}, {"text": "Geringer Preis", "correct": false, "because": "Qualität zählt"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Automatisierung im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SDN nutzt OpenFlow. b) VLANs sind hardwareunabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Switch-abhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein VLAN?', 5, '[{"text": "Komplexe Konfiguration", "correct": true, "because": "Erfordert Planung"}, {"text": "Begrenzte IDs", "correct": true, "because": "Maximal 4096"}, {"text": "Höhere Geschwindigkeit", "correct": false, "because": "Kein Nachteil"}, {"text": "Einfache Verwaltung", "correct": false, "because": "Nicht immer einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem VLAN für IoT-Geräte unwichtig?', 3, '[{"text": "Sicherheitsisolierung", "correct": false, "because": "Schutz entscheidend"}, {"text": "Broadcast-Reduktion", "correct": false, "because": "Effizienz nötig"}, {"text": "Hohe Rechenleistung", "correct": true, "because": "Switch-abhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht SDN die Netzwerksicherheit?', 3, '[{"text": "Ja", "correct": true, "because": "Zentrale Kontrolle ermöglicht Policies"}, {"text": "Nein", "correct": false, "because": "Sicherheit verbesserbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob VLANs ohne Switches möglich sind?', 2, '[{"text": "Nein", "correct": true, "because": "Switch für logische Trennung nötig"}, {"text": "Ja", "correct": false, "because": "Hardwareabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für dynamische Netzwerke?', 4, '[{"text": "SDN", "correct": true, "because": "Softwarebasiert und anpassbar"}, {"text": "VLAN", "correct": false, "because": "Statischer"}, {"text": "Manuelle Switches", "correct": false, "because": "Zu starr"}]');
